using System; using System.Data.Entity; using System.Web; using System.Web.Mvc; using System.Web.Optimization; using System.Web.Routing; using System.Web.Script.Serialization; using System.Web.Security; using OrderFlow.MVC.Data; using OrderFlow.MVC.Security;
namespace OrderFlow.MVC { public class MvcApplication : HttpApplication { protected void Application_Start() { Database.SetInitializer(new SeedData()); AreaRegistration.RegisterAllAreas(); FilterConfig.RegisterGlobalFilters(GlobalFilters.Filters); RouteConfig.RegisterRoutes(RouteTable.Routes); BundleConfig.RegisterBundles(BundleTable.Bundles); } protected void Application_PostAuthenticateRequest() { var cookie = Request.Cookies[FormsAuthentication.FormsCookieName]; if (cookie == null) return; try { var ticket = FormsAuthentication.Decrypt(cookie.Value); var data = new JavaScriptSerializer().Deserialize<CustomPrincipalSerializeModel>(ticket.UserData); Context.User = new CustomPrincipal(ticket.Name, data.UserId, data.CustomerId, data.DisplayName, data.Role); } catch { FormsAuthentication.SignOut(); } } } }

